mapper.select:
SELECT

FROM t_recharge_flow_detail
WHERE 1 = 1

    AND from_shop_id = #{fromShopId}


    AND to_shop_id = #{toShopId}


    AND from_cust_code = #{fromCustCode}


    AND to_cust_code = #{toCustCode}


    AND operate_type = #{operateType}


    AND operate_time >= #{startTime}


    AND operate_time <= #{endTime}

ORDER BY operate_time DESC, id DESC
